/* eslint-disable no-undef */
/* eslint-disable no-console */
import React, { useState } from "react";
import { MapContainer, TileLayer, Marker, Popup, Circle } from "react-leaflet";
import "leaflet/dist/leaflet.css";
import L from "leaflet";

// Fix marker icons
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl:
    "https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon-2x.png",
  iconUrl:
    "https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon.png",
  shadowUrl:
    "https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-shadow.png",
});

export default function SafetyCheck() {
  const [latitude, setLatitude] = useState("");
  const [longitude, setLongitude] = useState("");
  const [result, setResult] = useState("");
  const [position, setPosition] = useState([25.3176, 82.9739]); // Default Varanasi

  const handleFetchLocation = () => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          const { latitude, longitude } = pos.coords;
          setLatitude(latitude);
          setLongitude(longitude);
          setPosition([latitude, longitude]);
        },
        (err) => {
          console.error(err);
          alert("Unable to fetch location");
        }
      );
    } else {
      alert("Geolocation is not supported by this browser.");
    }
  };

  const handleCheckSafety = async () => {
    try {
      const response = await fetch("http://localhost:5000/api/safety/check", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          latitude: parseFloat(latitude),
          longitude: parseFloat(longitude),
        }),
      });

      if (!response.ok) throw new Error("Network error");

      const data = await response.json();
      setResult(data.message);
    } catch (error) {
      console.error("Error checking safety:", error);
      setResult("Error checking safety");
    }
  };

  return (
    <div style={{ textAlign: "center", padding: "20px" }}>
      <h2 style={{ color: "#1E3A8A" }}>Smart Tourist Safety Check 🌍</h2>
      <button
        onClick={handleFetchLocation}
        style={{
          background: "#22C55E",
          color: "white",
          padding: "8px 16px",
          border: "none",
          borderRadius: "8px",
          cursor: "pointer",
          margin: "10px",
        }}
      >
        📍 Fetch My Location
      </button>
      <button
        onClick={handleCheckSafety}
        style={{
          background: "#2563EB",
          color: "white",
          padding: "8px 16px",
          border: "none",
          borderRadius: "8px",
          cursor: "pointer",
          margin: "10px",
        }}
      >
        ✅ Check Safety
      </button>

      {result && (
        <p
          style={{
            marginTop: "20px",
            fontWeight: "bold",
            color: result.includes("Safe") ? "green" : "red",
          }}
        >
          {result}
        </p>
      )}

      <div style={{ height: "400px", width: "80%", margin: "20px auto" }}>
        <MapContainer
          center={position}
          zoom={13}
          style={{ height: "100%", width: "100%", borderRadius: "12px" }}
        >
          <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
          <Marker position={position}>
            <Popup>You are here 🧭</Popup>
          </Marker>
          {result.includes("Risk") && (
            <Circle
              center={position}
              radius={500}
              pathOptions={{ color: "red", fillColor: "pink", fillOpacity: 0.3 }}
            />
          )}
        </MapContainer>
      </div>
    </div>
  );
}
